<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {session,logout} from '../auth'
import {useRouter} from 'vue-router'
const router=useRouter(),legs=ref<any[]>([]),wallets=ref<any[]>([]),wallet=ref(''),direction=ref('BUY'),quantity=ref(''),items=ref<any[]>([]),message=ref(''),busy=ref(false),menuOpen=ref(false)
const stateName=(state:string)=>({requesting:'询价中',quoted:'已报价',accepting:'确认中',executing:'执行中，未确认成交',confirmed:'已确认',expired:'已过期',rejected:'已拒绝',failed:'未成交',unknown:'结果未知'} as Record<string,string>)[state]||'未知'
const nextCursor=ref<string|null>(null)
const key='polysports_combo_legs',pendingKey='polysports_combo_pending';const pending=ref<any>(null),ack=ref(false)
async function api(path:string,options:RequestInit={}){const r=await fetch('/api/v1'+path,{credentials:'same-origin',cache:'no-store',...options});const body=await r.json();if(!r.ok){const e=new Error(body.error?.message||'请求失败');(e as any).code=body.error?.code;throw e}return body.data}
async function load(more=false){try{const [w,r]=await Promise.all([api('/wallets'),api('/combo-rfqs'+(more&&nextCursor.value?'?cursor='+encodeURIComponent(nextCursor.value):''))]);wallets.value=w.items;items.value=more?[...items.value,...r.items]:r.items;nextCursor.value=r.next_cursor||null;if(!wallet.value&&wallets.value.length)wallet.value=wallets.value[0].id}catch{message.value='读取钱包或组合记录失败。'}}
function remove(i:number){legs.value.splice(i,1);localStorage.setItem(key,JSON.stringify(legs.value))}
async function quote(){if(busy.value)return;busy.value=true;message.value='';const old=localStorage.getItem(pendingKey);if(old){message.value='上次询价结果未确认，请查询记录，勿重复询价。';busy.value=false;return}const id=crypto.randomUUID();try{localStorage.setItem(pendingKey,JSON.stringify({key:id,wallet_id:wallet.value}));pending.value={key:id,wallet_id:wallet.value}}catch{message.value='无法保存请求标识，未发送询价。';busy.value=false;return}try{await api('/combo-rfqs',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':session.csrf,'Idempotency-Key':id},body:JSON.stringify({wallet_id:wallet.value,direction:direction.value,quantity:quantity.value,legs:legs.value.map(x=>({market_link_id:x.market_link_id,outcome_id:x.outcome_id}))})});localStorage.removeItem(pendingKey);pending.value=null;await load();message.value='已记录组合询价，请核对报价和状态。'}catch(e){if((e as any)?.code==='COMBO_DISABLED'){localStorage.removeItem(pendingKey);pending.value=null;message.value='组合交易未启用，本次未发送询价。'}else message.value='询价结果未确认，请查看交易记录并独立核对，勿重复请求。'}finally{busy.value=false}}
async function accept(row:any){if(!row.quote||busy.value)return;busy.value=true;try{await api('/combo-rfqs/'+row.id+'/accept',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':session.csrf},body:JSON.stringify({quote_id:row.quote.id})});await load();message.value='已处理确认请求；执行中不代表成交。'}catch{message.value='确认结果未核实，请查看记录，不要重复提交。'}finally{busy.value=false}}
async function lookup(){if(!pending.value)return;try{const data=await api('/combo-rfqs/by-key/'+pending.value.key+'?wallet_id='+encodeURIComponent(pending.value.wallet_id));message.value='已找到记录，状态：'+data.state;if(!['requesting','unknown'].includes(data.state)){localStorage.removeItem(pendingKey);pending.value=null}await load()}catch{message.value='未能找到记录，请独立核对，不要重新询价。'}}
function clearPending(){if(!ack.value)return;localStorage.removeItem(pendingKey);pending.value=null;ack.value=false}
onMounted(()=>{try{legs.value=JSON.parse(localStorage.getItem(key)||'[]');pending.value=JSON.parse(localStorage.getItem(pendingKey)||'null')}catch{legs.value=[]}load()})
</script>
<template><div class="app-layout"><header class="mobile-header"><div class="brand">PolySports</div><button class="menu-button" :aria-expanded="menuOpen" aria-controls="primary-nav" @click="menuOpen=!menuOpen">菜单</button></header><aside id="primary-nav" class="sidebar" :class="{open:menuOpen}"><div class="brand sidebar-brand">PolySports</div><nav><RouterLink to="/">总览</RouterLink><RouterLink to="/sports/football">足球赛事</RouterLink><RouterLink to="/sports/nba">NBA 赛事</RouterLink><RouterLink to="/combos">组合交易</RouterLink><RouterLink to="/orders">交易记录</RouterLink><RouterLink to="/wallets">钱包状态</RouterLink><RouterLink to="/system">系统管理</RouterLink></nav></aside><main class="workspace combo-page"><div class="workspace-top"><span>工作台 / 组合交易</span><button class="text-button" @click="logout().then(()=>router.replace('/login'))">退出</button></div><h1>组合询价</h1><p>从赛事市场中选择至少两条腿。确认报价后可能使用真实资金；执行中不代表成交。</p><p role="status">{{message}}</p><section v-if="pending" class="welcome-card"><p>上次询价结果未确认，请先用原请求标识查询。</p><button class="text-button" @click="lookup">查询原请求</button><label><input type="checkbox" v-model="ack">我已独立核实外部状态，理解重复询价风险</label><button class="text-button" :disabled="!ack" @click="clearPending">清除本机待查记录</button></section><section class="welcome-card"><p v-if="!legs.length">请先在赛事中心选择已确认的市场选项。</p><p v-for="(leg,index) in legs" :key="leg.outcome_id">{{leg.label}} <button class="text-button" @click="remove(index)">移除</button></p><label>钱包 <select v-model="wallet"><option v-for="w in wallets" :key="w.id" :value="w.id">{{w.label}} · {{w.wallet_address}}</option></select></label><label>方向 <select v-model="direction"><option value="BUY">买入</option><option value="SELL">卖出</option></select></label><label>{{direction==='BUY'?'最高预算（含费用）':'出售份额'}} <input v-model="quantity" inputmode="decimal"></label><button class="text-button" :disabled="busy||legs.length<2||!wallet||!quantity" @click="quote">请求真实报价</button></section><section class="welcome-card"><h2>组合记录</h2><button class="text-button" @click="load()">刷新状态</button><p v-if="!items.length">暂无组合记录。</p><article v-for="row in items" :key="row.id" class="market-card"><p>状态：{{stateName(row.state)}} · 方向：{{row.direction}} · 数量：{{row.quantity}} · 钱包：{{row.wallet_address}}</p><p v-for="leg in row.legs" :key="leg.outcome_id">{{leg.home}} 对 {{leg.away}} · {{leg.market_question}} · {{leg.outcome_label}} · {{new Date(leg.starts_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}} UTC+8</p><p>RFQ：{{row.external_rfq_id || '未知'}} · {{row.error_code || ''}}</p><p v-if="row.quote">报价：{{row.quote.price}} · 实际需求：{{row.quote.total_required}} · {{row.direction==='BUY'?'预计组合份额':'扣费后收入'}}：{{row.quote.net_receive ?? '未知'}} · 截止：{{row.quote.expires_at}}</p><button v-if="row.state==='quoted' && row.quote" class="text-button" :disabled="busy" @click="accept(row)">确认接受真实资金报价</button><p v-if="row.state==='unknown'">结果未知；请勿重复操作。</p></article><button v-if="nextCursor" class="text-button" @click="load(true)">加载更多</button></section></main></div></template>
